import { computed } from 'vue'
import { useRouter, useRoute } from 'vue-router'

const router = useRouter()
const route = useRoute()

// Teruskan konteks marketing terpilih (m = id_marketing, nm = nama, mu = user_id).
const passQuery = computed(() => {
	const q = {}
	if (route.query.m) q.m = route.query.m
	if (route.query.nm) q.nm = route.query.nm
	if (route.query.mu) q.mu = route.query.mu
	return q
})
const marketingName = computed(() => route.query.nm || '')

// Opsi "Register: Sudah Pencairan" hanya muncul saat dibuka dari List Marketing
// (ada konteks marketing). Mengarah ke list Data Pengajuan, difilter status
// "Sudah Pencairan" + marketing terpilih (field `marketing` = user_id).
const fromListMarketing = computed(() => !!route.query.m)
const registerQuery = computed(() => {
	const q = { status: 'Sudah Pencairan' }
	// `m` diteruskan agar tombol back Data Pengajuan bisa merekonstruksi halaman
	// FID/FPD ini lengkap (menu "Register: Sudah Pencairan" ikut tampil).
	if (route.query.m) q.m = route.query.m
	if (route.query.mu) q.mu = route.query.mu
	if (route.query.nm) q.nm = route.query.nm
	return q
})

